sition or assent."],"semantic_bindings":["recipient is the person asked","subject is the prototype pump","the report log records the request"]},{"schema_version":"world-substrate-action-mechanic/v0","mechanic_id":"record-evidence-investigation","version":"1.0","action_kind":"investigate-evidence","rationale":"Record the actor's supplied interpretation of active information about the specified subject. This records an interpretation without converting it into a stance or assent.","actor_selector":{"categories":["actor"],"components":["member","report_log"]},"participants":{"subject":{"categories":["information"],"components":["information"]},"pump_1":{"categories":["prototype-pump","pump-1"],"components":["pump_1"]}},"parameters":{"interpretation":["Sensor channel C drifted 8 units in validation batch V17.","Validation failed.","The evidence is inconclusive."]},"checks":[{"label":"the specified information is active","left":{"participant":{"name":"subject","path":"components.information.active"}},"op":"eq","right":{"literal":true}},{"label":"the interpretation is not empty","left":{"action_field":"interpretation"},"op":"ne","right":{"literal":""}},{"label":"the information is with the investigator","left":{"participant":{"name":"actor","path":"location.location_id"}},"op":"eq","right":{"participant":{"name":"subject","path":"location.location_id"}}},{"label":"the prototype pump is with the investigator","left":{"participant":{"name":"actor","path":"location.location_id"}},"op":"eq","right":{"participant":{"name":"pump_1","path":"location.location_id"}}}],"effects":[{"participant":"actor","path":"components.report_log.entries","op":"append_report","value":{"action_field":"interpretation"}}],"limits":["Only active information can be investigated by this mechanic.","The mechanic records the actor's interpretation; it does not establish that the interpretation is correct or that the actor or anyone else assents.","This mechanic does not infer access from delivery records