          "type": "entity_ref"
        },
        {
          "name": "pump_1",
          "type": "entity_ref"
        }
      ],
      "kind": "ignore-claim"
    }
  ],
  "allowed_state_paths": [
    "location.location_id",
    "ownership.owner_ref",
    "portable.portable",
    "components.member.role",
