k.request_evidence_done","op":"set","value":{"literal":false}}],"timing":"each_round"},{"process_id":"reset-investigate-evidence-work-flag","rationale":"The investigation work flag marks completion within a round; reset it so investigation remains available in later rounds.","selector":{"categories":["actor"],"components":["work"]},"checks":[{"label":"an investigation was recorded","left":{"participant":{"name":"it","path":"components.work.investigate_evidence_done"}},"op":"eq","right":{"literal":true}}],"effects":[{"participant":"it","path":"components.work.investigate_evidence_done","op":"set","value":{"literal":false}}],"timing":"each_round"},{"process_id":"reset-ignore-claim-work-flag","rationale":"The ignore-claim work flag marks completion within a round; reset it so the choice remains available in later rounds.","selector":{"categories":["actor"],"components":["work"]},"checks":[{"label":"a claim was ignored","left":{"participant":{"name":"it","path":"components.work.ignore_claim_done"}},"op":"eq","right":{"literal":true}}],"effects":[{"participant":"it","path":"components.work.ignore_claim_done","op":"set","value":{"literal":false}}],"timing":"each_round"}],"terminal":null}"}, {"role": "user", "content": "The local causal compiler rejected that proposal. Compiler error: ActionDeclarationError: participants.subject must constrain at least one category or component. Return a corrected JSON object only. State paths in participant/path and effect/path fields must be copied EXACTLY from allowed_state_paths; do not abbreviate component containers (for example use portable.portable, not portable)."}]

